from ortools.linear_solver import pywraplp
import json

def solve_cutting_problem():
    W = 20
    H = 15

    categories = [1, 2, 3]
    dim_w = {1: 5, 2: 6, 3: 4}
    dim_h = {1: 4, 2: 3, 3: 4}
    value = {1: 20, 2: 18, 3: 16}
    max_qty = {1: 2, 2: 2, 3: 2}

    solver = pywraplp.Solver.CreateSolver("SCIP")
    INF = solver.infinity()
    solver.SetTimeLimit(30000)

    place = {}
    x = {}
    y = {}
    rot = {}

    for c in categories:
        place[c] = {}
        x[c] = {}
        y[c] = {}
        rot[c] = {}
        for i in range(1, max_qty[c] + 1):
            place[c][i] = solver.BoolVar(f"place_{c}_{i}")
            x[c][i] = solver.NumVar(0, W, f"x_{c}_{i}")
            y[c][i] = solver.NumVar(0, H, f"y_{c}_{i}")
            rot[c][i] = solver.BoolVar(f"rot_{c}_{i}")

    for c in categories:
        for i in range(1, max_qty[c] + 1):
            M = W + H
            solver.Add(x[c][i] + dim_w[c] <= W + 
                      rot[c][i] * (dim_w[c] - dim_h[c]) + (1 - place[c][i]) * M)

            solver.Add(y[c][i] + dim_h[c] <= H + 
                      rot[c][i] * (dim_h[c] - dim_w[c]) + (1 - place[c][i]) * M)

            solver.Add(x[c][i] <= place[c][i] * W)
            solver.Add(y[c][i] <= place[c][i] * H)

    all_pieces = []
    for c in categories:
        for i in range(1, max_qty[c] + 1):
            all_pieces.append((c, i))

    for idx1, (c1, i1) in enumerate(all_pieces):
        for idx2, (c2, i2) in enumerate(all_pieces):
            if idx1 >= idx2:
                continue

            cond1 = solver.BoolVar(f"cond1_{c1}_{i1}_{c2}_{i2}")
            cond2 = solver.BoolVar(f"cond2_{c1}_{i1}_{c2}_{i2}")
            cond3 = solver.BoolVar(f"cond3_{c1}_{i1}_{c2}_{i2}")
            cond4 = solver.BoolVar(f"cond4_{c1}_{i1}_{c2}_{i2}")

            M = W + H
            solver.Add(x[c1][i1] + dim_w[c1] <= x[c2][i2] + 
                      rot[c1][i1] * (dim_w[c1] - dim_h[c1]) + (1 - cond1) * M)

            solver.Add(x[c2][i2] + dim_w[c2] <= x[c1][i1] + 
                      rot[c2][i2] * (dim_w[c2] - dim_h[c2]) + (1 - cond2) * M)

            solver.Add(y[c1][i1] + dim_h[c1] <= y[c2][i2] + 
                      rot[c1][i1] * (dim_h[c1] - dim_w[c1]) + (1 - cond3) * M)

            solver.Add(y[c2][i2] + dim_h[c2] <= y[c1][i1] + 
                      rot[c2][i2] * (dim_h[c2] - dim_w[c2]) + (1 - cond4) * M)

            solver.Add(cond1 + cond2 + cond3 + cond4 + (1 - place[c1][i1]) + (1 - place[c2][i2]) >= 1)

    objective = solver.Objective()
    for c in categories:
        for i in range(1, max_qty[c] + 1):
            objective.SetCoefficient(place[c][i], value[c])
    objective.SetMaximization()

    status = solver.Solve()

    if status == pywraplp.Solver.OPTIMAL or status == pywraplp.Solver.FEASIBLE:
        placements = []
        total_value = 0

        for c in categories:
            for i in range(1, max_qty[c] + 1):
                if place[c][i].solution_value() > 0.5:
                    x_val = x[c][i].solution_value()
                    y_val = y[c][i].solution_value()
                    rot_val = int(rot[c][i].solution_value() > 0.5)
                    placements.append([
                        c - 1,
                        round(x_val),
                        round(y_val),
                        rot_val
                    ])
                    total_value += value[c]

        print(json.dumps({
            "placements": placements,
            "total_value": total_value
        }))
    else:
        print(json.dumps({
            "placements": [],
            "total_value": 0
        }))

if __name__ == "__main__":
    solve_cutting_problem()
